-- Insert Quiz Questions for Lesson: Real-World Form Examples

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 7 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 7 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'real-world-examples' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson real-world-examples not found in module 7';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What fields might a coach use for a discovery call form?', 
    '["Full business history and budget","First Name, Email, Phone, What are you looking for support with?","Social security number and birth date","Credit card information"]'::jsonb,
    'First Name, Email, Phone, What are you looking for support with?',
    'A coach''s discovery call form should be simple: name, contact info, and what they need support with. Enough to start a conversation.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What follow-up should happen after a guide download form?', 
    '["Nothing, the download is enough","Add tag, send guide by email, start nurture workflow","Immediately call the person 10 times","Delete the lead"]'::jsonb,
    'Add tag, send guide by email, start nurture workflow',
    'After a guide download, tag the lead, deliver the guide by email, and start a nurture workflow to build the relationship over time.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why would a speaker need different fields than a consultant?', 
    '["They do not need different fields","Different businesses need different information to evaluate and follow up on leads","Speakers never use forms","Consultants do not need contact information"]'::jsonb,
    'Different businesses need different information to evaluate and follow up on leads',
    'Different business types need different information. A speaker needs event details, while a consultant might need service type and challenges.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
